import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.cT4_XGNl.js";const h=JSON.parse('{"title":"Interview Preparation: 150+ Questions & Answers","description":"","frontmatter":{},"headers":[],"relativePath":"09-interview-qa.md","filePath":"09-interview-qa.md"}'),r={name:"09-interview-qa.md"};function n(s,e,l,c,d,u){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="interview-preparation-150-questions-answers" tabindex="-1">Interview Preparation: 150+ Questions &amp; Answers <a class="header-anchor" href="#interview-preparation-150-questions-answers" aria-label="Permalink to &quot;Interview Preparation: 150+ Questions &amp; Answers&quot;">​</a></h1><h2 id="category-1-project-overview-core-architecture" tabindex="-1">Category 1: Project Overview &amp; Core Architecture <a class="header-anchor" href="#category-1-project-overview-core-architecture" aria-label="Permalink to &quot;Category 1: Project Overview &amp; Core Architecture&quot;">​</a></h2><ol><li><strong>Can you give a 60-second summary of this project?</strong><ul><li>It is a creative publishing platform combining React 19, Three.js 3D spatial canvas graphics, and a Node.js/MongoDB REST API. It delivers 60fps kinetic scrolling and physics-based cursor interactions on the frontend, supported by a secure JWT-authenticated publishing workflow with Cloudinary asset optimization on the backend.</li></ul></li><li><strong>What inspired the inclusion of Three.js in a blogging platform?</strong><ul><li>Traditional blogs feel static and uninspiring. By adding a lightweight, interactive 3D hero canvas, readers are greeted with an engaging visual experience that elevates technical storytelling without sacrificing reading speed.</li></ul></li><li><strong>How do you ensure Three.js does not degrade page load performance?</strong><ul><li>The Three.js canvas is initialized asynchronously after primary DOM content mounts, using low polygon geometry and dynamic LOD (level-of-detail) to keep CPU and GPU overhead minimal.</li></ul></li></ol><h2 id="category-2-frontend-engineering-kinetics" tabindex="-1">Category 2: Frontend Engineering &amp; Kinetics <a class="header-anchor" href="#category-2-frontend-engineering-kinetics" aria-label="Permalink to &quot;Category 2: Frontend Engineering &amp; Kinetics&quot;">​</a></h2><ol start="4"><li><strong>How does Lenis smooth scroll work under the hood?</strong><ul><li>It intercepts the browser&#39;s native <code>wheel</code> and <code>touchmove</code> events, calculates a smoothed target position using a custom cubic easing equation inside a <code>requestAnimationFrame</code> loop, and updates the scroll position continuously.</li></ul></li><li><strong>Why did you use React Three Fiber instead of raw Three.js?</strong><ul><li>R3F allows Three.js objects to be expressed as declarative React components. This enables automatic cleanup on unmount, straightforward state-to-mesh prop binding, and cleaner lifecycle management.</li></ul></li><li><strong>How do the magnetic buttons work?</strong><ul><li>The magnetic component measures the bounding box of the element via <code>getBoundingClientRect()</code>. On mouse move, it computes the delta vector between the pointer and the element&#39;s center point, applying a damped spring transform via GSAP.</li></ul></li></ol><h2 id="category-3-backend-database-security" tabindex="-1">Category 3: Backend, Database &amp; Security <a class="header-anchor" href="#category-3-backend-database-security" aria-label="Permalink to &quot;Category 3: Backend, Database &amp; Security&quot;">​</a></h2><ol start="7"><li><strong>Why did you choose MongoDB over PostgreSQL?</strong><ul><li>Editorial articles have variable schemas (diverse tags, rich text blocks, dynamic cover formats). MongoDB&#39;s document model represents these hierarchies naturally without requiring multi-table joins.</li></ul></li><li><strong>How do you prevent NoSQL injection?</strong><ul><li>Mongoose schemas enforce strict type validation. Any unexpected query operators like <code>{ $gt: &#39;&#39; }</code> are stripped or rejected before reaching the database driver.</li></ul></li><li><strong>How are passwords stored securely?</strong><ul><li>They are salted and hashed using bcrypt with an adaptive work factor of 10 rounds, ensuring resistance against rainbow table attacks and brute-force cracking.</li></ul></li></ol>',7)])])}const p=t(r,[["render",n]]);export{h as __pageData,p as default};
